import {
  getOrgType,
  saveOrgTypeAPI,
  deleteOrgTypeAPI,
  getOrgTypeCombo
} from '../../../services/Masters/MatersService';

export const fetchGlobalTypes = async (globalTypeCategoryID, searchQuery, statusID) => {
  try {
    const response = await getOrgType(globalTypeCategoryID, searchQuery, statusID);

    if (response && response.success) {
      return response.returnResult || [];
    } else {
      window.showSnackbar({
        message: response?.message || 'An error occurred while fetching org types',
        variant: 'error'
      });
      console.log('Error fetching org types:', response?.message);
      return [];
    }
  } catch (err) {
    window.showSnackbar({
      message: err.message || 'An error occurred while fetching org types',
      variant: 'error'
    });
    console.log('Error fetching org types:', err);
    return [];
  }
};

