export const saveOrgType = async (payload, customSuccessMsg, customErrorMsg) => {
  try {
    const response = await saveOrgTypeAPI(payload);
    if (!response || !response.success) {
      console.log('response?.message', response?.message || 'Failed to save globle type');
      window.showSnackbar({
        message: customErrorMsg || `Failed to save globle type`,
        variant: 'error'
      });
    } else {
      window.showSnackbar({
        message: customSuccessMsg || `globle type saved successfully`,
        variant: 'success'
      });
    }
    return response;
  } catch (err) {
    const errorMessage =
      err?.message || (typeof err === 'string' ? err : 'Failed to save globle type');
    window.showSnackbar({
      message: errorMessage,
      variant: 'error'
    });
    console.log('Failed to save globle type:', err);
    return { success: false, message: errorMessage };
  }
};

