export const generate12DigitAlphaNumericCode = () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';

  for (let i = 0; i < 12; i++) {
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }

  return code;
};

export const isDcrScreen = () => {
  const location = useLocation();
  const dcrPaths = ['/dcr-list', '/dcr-clients', '/dcr-city', '/dcr-area'];
  return dcrPaths.includes(location.pathname);
};

export const userScreenAccess = (path = null) => {
  const location = path ? { pathname: path } : useLocation();
  const { getMenuList } = useMenu();
  // Search for matching menu item in MenuListFlat from context
  const menuListFlat = getMenuList();
  for (const menu of menuListFlat) {
    if (menu.subMenus && menu.subMenus.length > 0) {
      for (const subMenus of menu.subMenus) {
        if (subMenus.routingKey === location.pathname) {
          return {
            hasListPermission: subMenus.hasListPermission,
            hasAddPermission: subMenus.hasAddPermission,
            hasEditPermission: subMenus.hasEditPermission,
            hasDeletePermission: subMenus.hasDeletePermission
          };
        }
      }
    }
  }

  // Return default permissions if route not found
  return {
    hasListPermission: false,
    hasAddPermission: false,
    hasEditPermission: false,
    hasDeletePermission: false,
    IsAssigned: false
  };
};

