export const useUserHasPermission = () => {
  const location = useLocation();
  const { getMenuList } = useMenu();

  // Search for matching menu item in MenuListFlat from context
  const menuListFlat = getMenuList();
  for (const menu of menuListFlat) {
    if (menu.subMenus && menu.subMenus.length > 0) {
      for (const subMenus of menu.subMenus) {
        if (subMenus.routingKey === location.pathname) {
          return subMenus.hasListPermission;
        }
      }
    }
  }

  // Return default permissions if route not found
  return false;
};

export const IsAdmins = () => {
  const { getAdmins } = useMenu();
  const admins = getAdmins();
  const userDetails = JSON.parse(localStorage.getItem(localStorageKeyName));
  return admins.includes(userDetails?.role);
};

export const formatDate = (date) => {
  if (!date) return null;
  return dayjs(date).format('YYYY-MM-DD');
};

export const formatDateTime = (date) => {
  if (!date) return null;
  return dayjs(date).format('YYYY-MM-DDTHH:mm:ss');
};