import {
  getUserRightsAPI,
  getUserRightsMenuAPI,
  saveUserRightsAPI
} from '../../services/UserRights';

export const fetchUserRights = async (roleGUID) => {
  try {
    const response = await getUserRightsAPI(roleGUID);

    if (response && response.success) {
      return response.returnResult || [];
    } else {
      console.log('Error fetching user rights:', response?.message);
      return [];
    }
  } catch (err) {
    console.log('Error fetching user rights:', err);
    return [];
  }
};

