export const saveUserRights = async (payload, successMsg, errorMsg) => {
  try {
    const user = JSON.parse(localStorage.getItem('userDetails'));
    const apiPayload = {
      ...payload,
      createdGUID: user.userGUID,
      createdByGUID: user.userGUID,
      modifiedGUID: user.userGUID,
      createdDate: new Date(),
      modifiedDate: new Date()
    };
    const response = await saveUserRightsAPI(apiPayload);

    if (response && response.success) {
      window.showSnackbar({
        message: successMsg || 'User rights saved successfully',
        variant: 'success'
      });
      return response;
    } else {
      window.showSnackbar({
        message: errorMsg || response?.message || 'An error occurred while saving user rights',
        variant: 'error'
      });
      console.log('Error saving user rights:', response?.message);
      return response;
    }
  } catch (err) {
    window.showSnackbar({
      message: errorMsg || err.message || 'An error occurred while saving user rights',
      variant: 'error'
    });
    console.log('Error saving user rights:', err);
    return { success: false };
  }
};
