import {
  getCityList,
  saveCityAPI,
  deleteCityAPI,
  getCityListCombo
} from '../../../services/Masters/MatersService';

export const fetchCitys = async (statusGUId) => {
  try {
    const response = await getCityList(statusGUId);

    if (response && response.success) {
      return response.returnResult || [];
    } else {
      window.showSnackbar({
        message: response?.message || 'An error occurred while fetching citys',
        variant: 'error'
      });
      console.log('Error fetching citys:', response?.message);
      return [];
    }
  } catch (err) {
    window.showSnackbar({
      message: err.message || 'An error occurred while fetching citys',
      variant: 'error'
    });
    console.log('Error fetching citys:', err);
    return [];
  }
};

