export const saveCity = async (payload, customSuccessMsg, customErrorMsg) => {
  try {
    const response = await saveCityAPI(payload);
    if (!response || !response.success) {
      console.log('response?.message', response?.message || 'Failed to save city');
      window.showSnackbar({
        message: customErrorMsg || `Failed to save city`,
        variant: 'error'
      });
    } else {
      window.showSnackbar({
        message: customSuccessMsg || `city saved successfully`,
        variant: 'success'
      });
    }
    return response;
  } catch (err) {
    const errorMessage = err?.message || (typeof err === 'string' ? err : 'Failed to save city');
    window.showSnackbar({
      message: errorMessage,
      variant: 'error'
    });
    console.log('Failed to save city:', err);
    return { success: false, message: errorMessage };
  }
};

