import {
  getAreaList,
  saveAreaAPI,
  deleteAreaAPI,
  getAreaListCombo
} from '../../../services/DCR/DCRService';

export const fetchDcrAreas = async (statusId) => {
  try {
    const response = await getAreaList(statusId);

    if (response && response.success) {
      return response.returnResult || [];
    } else {
      window.showSnackbar({
        message: response?.message || 'An error occurred while fetching Areas',
        variant: 'error'
      });
      console.log('Error fetching Areas:', response?.message);
      return [];
    }
  } catch (err) {
    window.showSnackbar({
      message: err.message || 'An error occurred while fetching Areas',
      variant: 'error'
    });
    console.log('Error fetching Areas:', err);
    return [];
  }
};

