export const saveDcrArea = async (payload, customSuccessMsg, customErrorMsg) => {
  try {
    const response = await saveAreaAPI(payload);
    if (!response || !response.success) {
      console.log('response?.message', response?.message || 'Failed to save Area');
      window.showSnackbar({
        message: customErrorMsg || `Failed to save Area`,
        variant: 'error'
      });
    } else {
      window.showSnackbar({
        message: customSuccessMsg || `Area saved successfully`,
        variant: 'success'
      });
    }
    return response;
  } catch (err) {
    const errorMessage = err?.message || (typeof err === 'string' ? err : 'Failed to save Area');
    window.showSnackbar({
      message: errorMessage,
      variant: 'error'
    });
    console.log('Failed to save Area:', err);
    return { success: false, message: errorMessage };
  }
};

